/**
 * What each holding cost, what it is worth now and what it has gained, worked out from its buys, its own price and,
 * for gold, the gold rate a person or a feed says.
 *
 * WHAT IT COST. A holding with buys counts their grams or shares into `qty` and what they cost, fees in, into `cost`,
 * and `unit_cost` is that cost spread over the count. Each buy's own `paid` is its count times its price, plus its fees.
 * A holding with no buys is costed as before, its count times what one cost, so a holding written before buys existed
 * keeps every number it had. Buys in two currencies are never added: the holding keeps its own count and cost.
 *
 * WHAT IT IS WORTH, in this order: the holding's own price ("Worth each now"), when somebody gave one; for gold, the
 * newest gold rate for its karat, or else the newest rate of any karat turned to this one by their purities (the 24k
 * rate times the karat over 24, a 21k rate times 18 over 21 for 18k gold), so gold is valued from the first rate anybody
 * sets, feed or no feed; and else what it cost. `valued_by` says which of the three it was, so a page can say a value
 * is only what was paid. GOLD WITH A COUNT AND A RATE IS VALUED EVEN WITH NO COST: a bracelet nobody knows the price of
 * is still worth its grams, it only has no gain.
 *
 * A HOLDING WITH NO BUYS AND NO PRICE EACH keeps the cost somebody wrote on it, and is costed by that.
 *
 * WHAT IT GAINED is its worth less its cost, and the gain over the cost as a percent, said only when something other
 * than the cost priced it and both are in one currency. A holding that stands at what it cost has no gain, not a gain
 * of nought.
 *
 * THE GOLD RATE. One row a karat is current: the newest by its day, and by when it was written on a tie. A rate written
 * with no day is dated today. A new rate marks itself current, the one before it not, and every gold holding is worked
 * out again against it.
 *
 * STARTED BY A RULE with the row that moved: a holding is worked out; a buy is priced and its holding worked out (a buy
 * deleted, or moved to another holding, works out every holding, since which holding it left is not said); a gold rate is marked and
 * every gold holding worked out. STARTED BY THE CLOCK once a day, with no row, it marks the rates and works out every
 * holding nothing has worked out yet, which is how a record that held holdings before this version gains its gains with
 * nobody writing a row again, then the gold holdings and the first page of the rest. The unvalued and the gold are read past
 * the first fifty, by number; only that last page is one page of fifty.
 *
 * A PRICE WRITTEN WITH NO DAY IS STAMPED WITH TODAY in `priced_on`, and a price said again is dated again when the rule
 * says the price moved and the day did not (`changed`, the fields the write moved, comma separated). A day somebody
 * wrote is never written over, and a price taken away takes its day with it. Nothing is written to a row that already
 * says what this would write.
 */

/** A karat's share of pure gold. */
const PURITY = { '24k': 24, '22k': 22, '21k': 21, '18k': 18 };

const amount = (m) => m !== null && typeof m === 'object' && typeof m.amount === 'number' && typeof m.currency === 'string';
const same = (a, b) => (amount(a) && amount(b) ? a.amount === b.amount && a.currency === b.currency : !amount(a) && !amount(b));
const number = (n) => typeof n === 'number' && Number.isFinite(n);
/** Counts are kept to six places, so a sum of grams reads 46.5 and not 46.50000000000001. */
const tidy = (n) => Math.round(n * 1e6) / 1e6;

/** What one buy paid: its count times its price, plus its fees in the same currency. `null` when it cannot be said. */
function paidOf(buy) {
  const { qty, price, fees } = buy.fields;
  if (!number(qty) || !amount(price)) return null;
  if (amount(fees) && fees.currency !== price.currency) return null;
  return { amount: Math.round(qty * price.amount) + (amount(fees) ? fees.amount : 0), currency: price.currency };
}

/** The current rate a karat: the newest row by its day, then by when it was written. */
function currentOf(rates) {
  const best = {};
  for (const r of rates) {
    const k = r.fields.karat;
    if (typeof k !== 'string' || !amount(r.fields.per_gram)) continue;
    const day = typeof r.fields.on === 'string' ? r.fields.on : '';
    const was = best[k];
    if (!was || day > was.day || (day === was.day && r.seq > was.seq)) best[k] = { day, seq: r.seq, id: r.id, per_gram: r.fields.per_gram };
  }
  return best;
}

/** What a gram of this karat is worth by the rates, or `null`. Not rounded, so the holding's worth is rounded once. */
function rateFor(current, karat) {
  if (typeof karat !== 'string' || PURITY[karat] === undefined) return null;
  if (current[karat]) return current[karat].per_gram;
  /* THE 24K RATE FIRST, then the newest of any other karat, each turned to this karat by their purities. */
  const others = Object.entries(current).filter(([k]) => PURITY[k] !== undefined);
  const pure = current['24k'];
  const from = pure ? ['24k', pure] : others.sort(([, a], [, b]) => (b.day > a.day ? 1 : b.day < a.day ? -1 : b.seq - a.seq))[0];
  if (!from) return null;
  const [k, rate] = from;
  return { amount: (rate.per_gram.amount * PURITY[karat]) / PURITY[k], currency: rate.per_gram.currency };
}

/** Dates a rate nobody dated, and marks the newest a karat current and the rest not. */
function markRates(ctx, rates, today) {
  const undated = (r) => amount(r.fields.per_gram) && !(typeof r.fields.on === 'string' && r.fields.on !== '');
  const current = currentOf(rates.map((r) => (undated(r) ? { ...r, fields: { ...r.fields, on: today } } : r)));
  const ids = new Set(Object.values(current).map((c) => c.id));
  for (const r of rates) {
    const next = undated(r) ? { on: today } : {};
    const now = ids.has(r.id);
    if ((r.fields.live === true) !== now) next.live = now;
    if (Object.keys(next).length > 0) ctx.update('gold_rates#' + r.seq, next, r.version);
  }
  return current;
}

/** Works out one holding against its buys and the rates, and writes what moved. */
async function work(ctx, row, current, today, repriced) {
  if (!row) return;
  const f = row.fields;
  const buys = await every(ctx, 'holding_buys', { field: 'item', is: row.id });
  const next = {};

  let qty = f.qty;
  let cost = null;
  const paid = buys.map(paidOf);
  const currencies = new Set(paid.filter(Boolean).map((p) => p.currency));
  if (buys.length > 0 && paid.every(Boolean) && currencies.size === 1) {
    qty = tidy(buys.reduce((s, b) => s + b.fields.qty, 0));
    const [currency] = currencies;
    cost = { amount: paid.reduce((s, p) => s + p.amount, 0), currency };
    if (f.qty !== qty) next.qty = qty;
    const each = qty > 0 ? { amount: Math.round(cost.amount / qty), currency } : null;
    if (each && !same(f.unit_cost, each)) next.unit_cost = each;
    const first = buys.map((b) => b.fields.bought_on).filter((d) => typeof d === 'string').sort()[0];
    if (first && f.acquired_on !== first) next.acquired_on = first;
  } else if (number(qty) && amount(f.unit_cost)) {
    cost = { amount: Math.round(qty * f.unit_cost.amount), currency: f.unit_cost.currency };
  } else if (amount(f.cost)) {
    /* A COST WRITTEN ON THE HOLDING ITSELF, with no buys and nothing paid each: the gold bar bought for £3,100 and valued
       by the gold rate. Its gain is its worth less that, so Worth now less Paid in is Gain on the page. */
    cost = f.cost;
  }
  const gram = f.kind === 'gold' ? rateFor(current, f.karat) : null;
  if (!number(qty) || (cost === null && !amount(f.price) && !gram)) {
    if (Object.keys(next).length > 0) ctx.update('holdings#' + row.seq, next, row.version);
    return;
  }

  let value = cost;
  let by = 'cost';
  if (amount(f.price)) {
    value = { amount: Math.round(qty * f.price.amount), currency: f.price.currency };
    by = 'price';
  } else if (gram) {
    value = { amount: Math.round(qty * gram.amount), currency: gram.currency };
    by = 'gold_rate';
  }
  const gained = cost !== null && by !== 'cost' && value.currency === cost.currency;
  const gain = gained ? { amount: value.amount - cost.amount, currency: cost.currency } : null;
  const pct = gained && cost.amount > 0 ? Math.round(((value.amount - cost.amount) / cost.amount) * 1000) / 10 : null;

  if (cost !== null && !same(f.cost, cost)) next.cost = cost;
  if (!same(f.value, value)) next.value = value;
  if (f.valued_by !== by) next.valued_by = by;
  if (!same(f.gain, gain)) next.gain = gain;
  if ((number(f.gain_pct) ? f.gain_pct : null) !== pct) next.gain_pct = pct;
  if (amount(f.price) && (!f.priced_on || repriced) && f.priced_on !== today) next.priced_on = today;
  if (!amount(f.price) && f.priced_on) next.priced_on = null;
  if (Object.keys(next).length > 0) ctx.update('holdings#' + row.seq, next, row.version);
}

/**
 * Every row of a list that `where` lets through. A script's list is one page of fifty, in the list's own order and with
 * no cursor, so the rows are asked for by number instead: the top number is found by asking above the highest seen,
 * then (0, top] is cut in halves until each half comes back short. At most 60 reads; `short` says some were left.
 */
async function every(ctx, register, where) {
  const PAGE = 50;
  const READS = 60;
  let reads = 0;
  const ask = (above, upto) => {
    reads += 1;
    const parts = [...(where ? [where] : []), ...(above > 0 ? [{ field: 'seq', gt: above }] : []), ...(upto === null ? [] : [{ field: 'seq', lte: upto }])];
    return parts.length === 0 ? ctx.record.list(register) : ctx.record.list(register, parts.length === 1 ? parts[0] : { all: parts });
  };
  const first = await ask(0, null);
  if (first.length < PAGE) return first;
  const seen = new Map(first.map((r) => [r.id, r]));
  let top = Math.max(...first.map((r) => r.seq));
  for (;;) {
    if (reads >= READS) break;
    const above = await ask(top, null);
    for (const r of above) seen.set(r.id, r);
    if (above.length < PAGE) break;
    top = Math.max(...above.map((r) => r.seq));
  }
  const spans = [[0, top]];
  let short = false;
  while (spans.length > 0) {
    if (reads >= READS) {
      short = true;
      break;
    }
    const [a, b] = spans.pop();
    const page = await ask(a, b);
    for (const r of page) seen.set(r.id, r);
    if (page.length >= PAGE && b - a > 1) {
      const mid = Math.floor((a + b) / 2);
      spans.push([a, mid], [mid, b]);
    }
  }
  const rows = [...seen.values()];
  rows.short = short;
  return rows;
}

export default async function run(ctx) {
  const input = ctx.input !== null && typeof ctx.input === 'object' ? ctx.input : {};
  const today = typeof ctx.today === 'function' ? ctx.today() : ctx.now().slice(0, 10);
  const moved = typeof input.changed === 'string' ? input.changed.split(',') : [];
  const repriced = moved.includes('price') && !moved.includes('priced_on');
  const rates = await every(ctx, 'gold_rates');
  const id = typeof input.id === 'string' ? input.id : null;

  if (id !== null && input.register === 'holding_buys') {
    const buy = await ctx.record.get(id);
    const current = currentOf(rates);
    const paid = buy === null ? null : paidOf(buy);
    if (buy !== null && paid !== null && !same(buy.fields.paid, paid)) ctx.update('holding_buys#' + buy.seq, { paid }, buy.version);
    /* GONE, OR MOVED FROM ONE HOLDING TO ANOTHER: which holding it left is not said, so every holding is worked out. */
    if (buy === null || (input.op === 'update' && moved.includes('item'))) {
      for (const row of await every(ctx, 'holdings')) await work(ctx, row, current, today, false);
      return;
    }
    const holding = typeof buy.fields.item === 'string' ? await ctx.record.get(buy.fields.item) : null;
    await work(ctx, holding, current, today, false);
    return;
  }
  if (id !== null && input.register === 'gold_rates') {
    const current = markRates(ctx, rates, today);
    for (const row of await every(ctx, 'holdings', { field: 'kind', is: 'gold' })) await work(ctx, row, current, today, false);
    return;
  }
  if (id !== null) {
    await work(ctx, await ctx.record.get(id), currentOf(rates), today, repriced);
    return;
  }
  /* THE CLOCK: the rates, every holding nothing has worked out yet, the gold, and the first page of the rest, which
     catches a holding whose buy a rule could not start a run for on a busy day. */
  const current = markRates(ctx, rates, today);
  const done = new Set();
  const lists = [{ field: 'valued_by', empty: true }, { field: 'kind', is: 'gold' }, null];
  const rows = [];
  for (const where of lists) rows.push(...(await (where === null ? ctx.record.list('holdings') : every(ctx, 'holdings', where))));
  for (const row of rows) {
    if (done.has(row.id)) continue;
    done.add(row.id);
    await work(ctx, row, current, today, false);
  }
}

/**
 * One thing written down twice: an account that counts as cash and a holding with the same name. The account's balance
 * is in the cash and the holding's worth is in Holdings value, so the same thing may be counted twice. Asked once:
 * stop counting the account as cash, or keep counting it.
 *
 * WHAT IT READS. Once a day, the accounts that count as cash and are not closed, and the holdings. Two names are the
 * same when their letters are, whatever the capitals and wherever the spaces. A blank name matches nothing.
 *
 * WHAT IT WRITES. Nothing. The one change rides on the answer "Stop counting it" and is made by whoever picks it: the
 * account stops counting as cash and keeps its balance. "Keep counting it" changes nothing.
 *
 * ONE QUESTION TO A PAIR, EVER. The cause is the pair, by the two lines' own numbers, and the record holds one question
 * to a cause: a run that finds it waiting adds none, and a run that finds it answered asks nothing. So this keeps no
 * memory of its own. An account taken out of cash is no longer read, so it is not asked about either.
 *
 * ONE RUN ASKS ONE QUESTION, so with several pairs the one asked about turns with the day. Always asking about the
 * first would hand an answered pair back every night and never reach the second. Holdings and accounts are read past
 * the first page of fifty, by number.
 */
const same = (name) => (typeof name === 'string' ? name.normalize('NFKC').toLowerCase().replace(/\s+/gu, '') : '');

/**
 * Every row of a list that `where` lets through. A script's list is one page of fifty, in the list's own order and with
 * no cursor, so the rows are asked for by number instead: the top number is found by asking above the highest seen,
 * then (0, top] is cut in halves until each half comes back short. At most 60 reads; `short` says some were left.
 */
async function every(ctx, register, where) {
  const PAGE = 50;
  const READS = 60;
  let reads = 0;
  const ask = (above, upto) => {
    reads += 1;
    const parts = [...(where ? [where] : []), ...(above > 0 ? [{ field: 'seq', gt: above }] : []), ...(upto === null ? [] : [{ field: 'seq', lte: upto }])];
    return parts.length === 0 ? ctx.record.list(register) : ctx.record.list(register, parts.length === 1 ? parts[0] : { all: parts });
  };
  const first = await ask(0, null);
  if (first.length < PAGE) return first;
  const seen = new Map(first.map((r) => [r.id, r]));
  let top = Math.max(...first.map((r) => r.seq));
  for (;;) {
    if (reads >= READS) break;
    const above = await ask(top, null);
    for (const r of above) seen.set(r.id, r);
    if (above.length < PAGE) break;
    top = Math.max(...above.map((r) => r.seq));
  }
  const spans = [[0, top]];
  let short = false;
  while (spans.length > 0) {
    if (reads >= READS) {
      short = true;
      break;
    }
    const [a, b] = spans.pop();
    const page = await ask(a, b);
    for (const r of page) seen.set(r.id, r);
    if (page.length >= PAGE && b - a > 1) {
      const mid = Math.floor((a + b) / 2);
      spans.push([a, mid], [mid, b]);
    }
  }
  const rows = [...seen.values()];
  rows.short = short;
  return rows;
}

export default async function run(ctx) {
  const holdings = await every(ctx, 'holdings');
  if (holdings.length === 0) return null;
  const accounts = (await every(ctx, 'accounts', { field: 'liquid', is: true })).filter((a) => a.fields.liquid === true && a.fields.state !== 'closed');
  const pairs = [];
  for (const account of accounts) {
    const name = same(account.fields.name);
    if (name === '') continue;
    for (const holding of holdings) if (same(holding.fields.label) === name) pairs.push({ account, holding });
  }
  if (pairs.length === 0) return null;
  const day = Math.round(Date.parse(`${ctx.today()}T00:00:00Z`) / 86_400_000);
  const { account, holding } = pairs[day % pairs.length];
  const name = String(account.fields.name).trim().replace(/\s+/gu, ' ');
  return {
    ask: {
      cause: `holdings.twin:${account.seq}:${holding.seq}`,
      question: `${name} is an account and a holding. It may be counted twice. Stop counting the account as cash?`,
      about: name,
      options: [
        {
          id: 'stop',
          label: 'Stop counting it',
          because: 'The account keeps its balance and is left out of your cash. The holding is counted as it is.',
          patches: [{ id: `accounts#${account.seq}`, version: account.version, fields: { liquid: false } }],
        },
        { id: 'keep', label: 'Keep counting it', because: 'Both are counted as they are, and this is not asked again.' },
      ],
    },
  };
}

/**
 * Today's gold rate from the world price, once a day, when the owner turns it on. Off until then: a record that never
 * chooses a source fetches nothing and is written nothing.
 *
 * TWO SOURCES, BOTH FREE AND WITH NO KEY, chosen in the `gold_source` setting:
 * - `world_price`: what an ounce of gold is worth in nearly every currency, the Egyptian pound among them, from the
 *   free currency-api on Cloudflare Pages, with its copy on jsDelivr asked when Pages does not answer. Pages first,
 *   because jsDelivr's `latest` was measured a day behind it (28 Oct against 29 Oct, asked the same minute).
 *   One answer a day, already in the record's money, dated by the answer's own day. Nothing else needs to be on.
 * - `spot_in_dollars`: the spot price of an ounce from gold-api.com, in dollars, live to the minute, turned into the
 *   record's money by the newest rate in Money's exchange rates. With no rate between dollars and that money it writes
 *   nothing and says so, rather than guess one.
 *
 * NO EGYPTIAN SHOP PRICE IS READ, because no Egyptian gold site answers one without a key or without reading its web
 * pages, and a feed that reads a page breaks the day the page is redrawn. Shops in Egypt sell above the world price
 * turned into pounds, so `gold_premium` adds a share over it, in percent, which the owner can set to what his jeweller
 * charges. It is 0 until he does.
 *
 * WHAT IT WRITES. A gram of 24k is an ounce over 31.1034768 grams, plus the premium; each other karat is that times
 * its karat over 24, as `holdings_cost` already prices a karat with no rate of its own. One row a karat, dated the day
 * the price is of, `from` set to `feed`, for 24k and for each karat the record's gold or its gold rates are in, so a
 * karat nobody holds is not written every day. `holdings_cost` marks the newest a karat as in use, as it does for a
 * rate typed by hand, and works every gold holding out again.
 *
 * A RATE A PERSON TYPED IS NEVER WRITTEN OVER, OR OUTRUN ON ITS OWN DAY. A karat that holds a rate set by hand (`from`
 * empty or `hand`) dated the feed's day or later is left alone that day, so a price the owner typed this morning is the
 * one in use. A rate of the feed's own for that karat and day is updated in place when the price moved, and nothing is
 * written when it did not. The feed only ever writes rows it marks as its own.
 *
 * THE MONEY. `gold_currency` names it, three letters; left empty it is the money the newest gold rate is in, else the
 * money the gold was bought in. A record with none of these writes nothing and says what to set. An amount is kept in
 * the currency's own minor units, as every money field is (`EXPONENT` below is the record's own table).
 */

const OUNCE_GRAMS = 31.1034768;
const PURITY = { '24k': 24, '22k': 22, '21k': 21, '18k': 18 };
const SOURCES = ['world_price', 'spot_in_dollars'];

const WORLD = ['https://latest.currency-api.pages.dev/v1/currencies/xau.min.json', 'https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/xau.min.json'];
const SPOT = 'https://api.gold-api.com/price/XAU';

/** The record's minor units a currency, `EXPONENT` in `packages/kernel/src/ingest.ts`; any other code is two. */
const EXPONENT = {
  CLF: 4, UYW: 4,
  BHD: 3, IQD: 3, JOD: 3, KWD: 3, LYD: 3, OMR: 3, TND: 3,
  BIF: 0, CLP: 0, DJF: 0, GNF: 0, ISK: 0, JPY: 0, KMF: 0, KRW: 0,
  PYG: 0, RWF: 0, UGX: 0, UYI: 0, VND: 0, VUV: 0, XAF: 0, XOF: 0, XPF: 0,
};

const CODE = /^[A-Z]{3}$/u;
const DAY = /^\d{4}-\d{2}-\d{2}$/u;
const amount = (m) => m !== null && typeof m === 'object' && typeof m.amount === 'number' && typeof m.currency === 'string';
const positive = (n) => typeof n === 'number' && Number.isFinite(n) && n > 0;
const codeOf = (v) => (typeof v === 'string' && CODE.test(v.trim().toUpperCase()) ? v.trim().toUpperCase() : null);

/** The settings as the run reads them, each held to what it may be. */
export function settingsOf(config) {
  const source = SOURCES.includes(config?.gold_source) ? config.gold_source : 'off';
  const premium = Number(config?.gold_premium);
  return {
    source,
    currency: codeOf(config?.gold_currency),
    premium: Number.isFinite(premium) && premium > -50 && premium < 100 ? premium : 0,
  };
}

/** The money the rates are written in: the setting, else the newest gold rate's, else the money the gold was bought in. */
export function currencyOf(set, rates, gold) {
  if (set) return set;
  const dated = rates.filter((r) => amount(r.fields.per_gram)).sort((a, b) => String(b.fields.on ?? '').localeCompare(String(a.fields.on ?? '')) || b.seq - a.seq);
  if (dated.length > 0) return dated[0].fields.per_gram.currency;
  for (const h of gold) for (const f of ['unit_cost', 'cost', 'price']) if (amount(h.fields[f])) return h.fields[f].currency;
  return null;
}

/** The karats to write: 24k, and each one the record's gold or its gold rates are in. */
export function karatsOf(rates, gold) {
  const held = new Set(['24k']);
  for (const r of [...rates, ...gold]) if (typeof r.fields.karat === 'string' && PURITY[r.fields.karat] !== undefined) held.add(r.fields.karat);
  return Object.keys(PURITY).filter((k) => held.has(k));
}

/** A gram of each karat, in minor units, from an ounce of pure gold in `currency`. */
export function gramsOf(ounce, currency, premium, karats) {
  const scale = 10 ** (EXPONENT[currency] ?? 2);
  const pure = (ounce / OUNCE_GRAMS) * (1 + premium / 100);
  return karats.map((karat) => ({ karat, per_gram: { amount: Math.round(((pure * PURITY[karat]) / 24) * scale), currency } }));
}

/**
 * What one dollar is worth in `currency` by Money's exchange rates, the newest of either way round, or `null`. A row
 * says one `currency` is `rate` of `base`, so dollars quoted in it multiply and it quoted in dollars divides.
 */
export function dollarsIn(fx, currency) {
  let best = null;
  for (const r of fx) {
    const { currency: c, base, rate, as_of } = r.fields;
    if (!positive(rate)) continue;
    const per = c === 'USD' && base === currency ? rate : c === currency && base === 'USD' ? 1 / rate : null;
    if (per === null) continue;
    const day = typeof as_of === 'string' ? as_of : '';
    if (best === null || day > best.day) best = { day, per };
  }
  return best === null ? null : best.per;
}

/** The world price: an ounce in `currency` and the day it is of, or a sentence saying why there is none. */
async function world(ctx, currency) {
  let said = 'the world price did not answer';
  for (const url of WORLD) {
    let r;
    try {
      r = await ctx.fetch(url);
    } catch {
      continue;
    }
    if (!r.ok) {
      said = `the world price answered ${r.status}`;
      continue;
    }
    const body = await r.json();
    const ounce = body?.xau?.[currency.toLowerCase()];
    if (!positive(ounce)) return { why: `the world price has no figure in ${currency}` };
    return { ounce, day: typeof body.date === 'string' && DAY.test(body.date) ? body.date : null };
  }
  return { why: said };
}

/** The spot price in dollars, turned into `currency` by Money's own rate. */
async function spot(ctx, currency) {
  let per = 1;
  if (currency !== 'USD') {
    const fx = [
      ...(await ctx.record.list('fx', { all: [{ field: 'currency', is: 'USD' }, { field: 'base', is: currency }] })),
      ...(await ctx.record.list('fx', { all: [{ field: 'currency', is: currency }, { field: 'base', is: 'USD' }] })),
    ];
    per = dollarsIn(fx, currency);
    if (per === null) return { why: `Money has no exchange rate between dollars and ${currency} to turn the spot price into it. Turn on Keep rates current in Money, or choose the world price` };
  }
  const r = await ctx.fetch(SPOT);
  if (!r.ok) return { why: `the spot price answered ${r.status}` };
  const body = await r.json();
  if (!positive(body?.price) || body.currency !== 'USD') return { why: 'the spot price came back without a price in dollars' };
  const day = typeof body.updatedAt === 'string' && DAY.test(body.updatedAt.slice(0, 10)) ? body.updatedAt.slice(0, 10) : null;
  return { ounce: body.price * per, day };
}

/**
 * The writes for one day's prices against the rates already there: a karat with a hand rate on that day or later is
 * passed over, the feed's own rate that day is updated when it moved, and any other karat gets a new rate.
 */
export function plan(rows, prices, day, note) {
  const out = { write: [], update: [], kept: [] };
  for (const p of prices) {
    const mine = rows.filter((r) => r.fields.karat === p.karat);
    if (mine.some((r) => r.fields.from !== 'feed' && typeof r.fields.on === 'string' && r.fields.on >= day)) {
      out.kept.push(p.karat);
      continue;
    }
    const same = mine.find((r) => r.fields.from === 'feed' && r.fields.on === day);
    if (!same) {
      out.write.push({ karat: p.karat, per_gram: p.per_gram, on: day, from: 'feed', note });
      continue;
    }
    const was = same.fields.per_gram;
    if (amount(was) && was.amount === p.per_gram.amount && was.currency === p.per_gram.currency && same.fields.note === note) continue;
    out.update.push({ row: same, patch: { per_gram: p.per_gram, note } });
  }
  return out;
}

export default async function run(ctx) {
  const set = settingsOf(ctx.config);
  if (set.source === 'off') return;

  const rates = await ctx.record.list('gold_rates', { field: 'karat', present: true });
  const gold = await ctx.record.list('holdings', { field: 'kind', is: 'gold' });
  const currency = currencyOf(set.currency, rates, gold);
  if (currency === null) {
    ctx.log('The gold rate was not set: there is no gold or gold rate yet to say which money to set it in. Write the money in the Gold rate in setting, such as EGP.');
    return;
  }

  const got = set.source === 'world_price' ? await world(ctx, currency) : await spot(ctx, currency);
  if (!positive(got.ounce)) {
    ctx.log(`The gold rate was not set today: ${got.why}.`);
    return;
  }
  const today = ctx.today();
  const day = got.day !== null && got.day <= today ? got.day : today;
  const prices = gramsOf(got.ounce, currency, set.premium, karatsOf(rates, gold));
  const note = set.premium === 0 ? 'World price' : `World price, plus ${set.premium}%`;

  const since = await ctx.record.list('gold_rates', { field: 'on', gte: day });
  const out = plan(since, prices, day, note);
  for (const w of out.write) ctx.write('gold_rates', w);
  for (const u of out.update) ctx.update('gold_rates#' + u.row.seq, u.patch, u.row.version);
  if (out.kept.length > 0) ctx.log(`Left the ${out.kept.join(', ')} gold rate as it was typed by hand.`);
}
